//! Cross-compatibility with the Node libraries the TypeScript server uses.
//! Fixtures were generated by `jose`, `@node-rs/argon2`, Node `scrypt`,
//! `bcryptjs` and `otplib`; the Rust implementation must read them unchanged.

use base64::Engine;
use serde_json::Value;

use orbitid_core::crypto::decrypt;
use orbitid_core::secrets::open_secret;
use orbitid_credentials::jwt::{Jwk, JwkSet, JwsAlgorithm, VerifyOptions};
use orbitid_credentials::mfa::{totp_code_at, totp_uri, verify_totp_code_at};
use orbitid_credentials::passwords::verify_password;

const FIXTURE: &str = include_str!("fixtures/cross_compat.json");

fn fixture() -> Value {
    serde_json::from_str(FIXTURE).expect("fixture is valid JSON")
}

fn text<'a>(fixture: &'a Value, key: &str) -> &'a str {
    fixture[key].as_str().expect("fixture string")
}

#[tokio::test]
async fn verifies_node_argon2_bcrypt_and_scrypt_hashes() {
    let fixture = fixture();
    assert!(
        verify_password(
            text(&fixture, "argon2_hash"),
            text(&fixture, "argon2_password")
        )
        .await
    );
    assert!(
        !verify_password(
            text(&fixture, "argon2_hash"),
            "definitely the wrong password"
        )
        .await
    );
    assert!(
        verify_password(
            text(&fixture, "argon2i_hash"),
            text(&fixture, "argon2i_password")
        )
        .await
    );
    assert!(
        verify_password(
            text(&fixture, "argon2d_hash"),
            text(&fixture, "argon2d_password")
        )
        .await
    );
    assert!(
        verify_password(
            text(&fixture, "bcrypt_hash"),
            text(&fixture, "bcrypt_password")
        )
        .await
    );
    assert!(!verify_password(text(&fixture, "bcrypt_hash"), "wrong").await);
    assert!(
        verify_password(
            text(&fixture, "scrypt_digest"),
            text(&fixture, "scrypt_password")
        )
        .await
    );
    assert!(!verify_password(text(&fixture, "scrypt_digest"), "wrong").await);
}

#[test]
fn reads_a_node_encrypted_signing_key() {
    let fixture = fixture();
    let encrypted = text(&fixture, "rsa_private_jwk_enc");
    let plaintext =
        decrypt(text(&fixture, "encryption_key"), encrypted).expect("decrypts with core crypto");
    let opened = open_secret(text(&fixture, "encryption_key"), encrypted);
    assert_eq!(opened, plaintext);
    let jwk = Jwk::from_value(&serde_json::from_str(&opened).unwrap()).unwrap();
    assert_eq!(jwk.kid(), Some("fixturekid"));
    assert_eq!(jwk.alg(), Some(JwsAlgorithm::RS256));
}

#[test]
fn rsa_pkcs1v15_signature_is_byte_identical_to_node() {
    let fixture = fixture();
    let jwk = Jwk::from_value(&fixture["rsa_private_jwk"]).unwrap();
    let signature = jwk
        .sign(
            JwsAlgorithm::RS256,
            text(&fixture, "rsa_signature_message").as_bytes(),
        )
        .unwrap();
    let encoded = base64::engine::general_purpose::URL_SAFE_NO_PAD.encode(signature);
    assert_eq!(encoded, text(&fixture, "rsa_signature_b64url"));
}

#[test]
fn verifies_node_signed_session_and_generic_jwts() {
    let fixture = fixture();
    let rsa = Jwk::from_value(&fixture["rsa_public_jwk"]).unwrap();
    let payload = orbitid_credentials::jwt::verify_jws(
        text(&fixture, "session_jwt_rs256"),
        &JwkSet::new(vec![rsa]),
        &VerifyOptions {
            algorithms: vec![JwsAlgorithm::RS256],
            issuer: Some(vec!["http://localhost:4000".into()]),
            audience: None,
            clock_tolerance_seconds: 60,
        },
    )
    .unwrap();
    assert_eq!(payload["sub"], "user_fixture");
    assert_eq!(payload["sid"], "sess_fixture");
    assert_eq!(payload["custom"], "kept");

    let hs_secret = base64::engine::general_purpose::URL_SAFE_NO_PAD
        .encode(text(&fixture, "hs256_secret").as_bytes());
    let hs =
        Jwk::from_value(&serde_json::json!({"kty":"oct","k":hs_secret,"alg":"HS256"})).unwrap();
    let payload = orbitid_credentials::jwt::verify_jws(
        text(&fixture, "hs256_jwt"),
        &JwkSet::new(vec![hs]),
        &VerifyOptions::default(),
    )
    .unwrap();
    assert_eq!(payload["hello"], "hs256");

    let ec = Jwk::from_value(&fixture["es256_public_jwk"]).unwrap();
    let payload = orbitid_credentials::jwt::verify_jws(
        text(&fixture, "es256_jwt"),
        &JwkSet::new(vec![ec]),
        &VerifyOptions::default(),
    )
    .unwrap();
    assert_eq!(payload["hello"], "es256");
}

#[test]
fn totp_matches_otplib_codes_and_uri() {
    let fixture = fixture();
    let secret = text(&fixture, "totp_secret");
    let epoch_seconds = fixture["totp_epoch_ms"].as_i64().unwrap() / 1000;
    assert_eq!(
        totp_code_at(secret, epoch_seconds).unwrap(),
        text(&fixture, "totp_code")
    );
    assert!(verify_totp_code_at(
        secret,
        text(&fixture, "totp_code"),
        epoch_seconds
    ));
    assert_eq!(
        totp_uri(secret, "ada@example.com", "OrbitID App"),
        text(&fixture, "totp_uri")
    );
}
